    except json.JSONDecodeError:
        pass

    # If both are strings, compare them directly
    if isinstance(CULTURAL_SPACE_NAME, str) and isinstance(AT_STREET, str):
        return int(CULTURAL_SPACE_NAME == AT_STREET)

